    options: { A: q.option_a, B: q.option_b, C: q.option_c, D: q.option_d },
    correctOption: q.correct_option,
    explanation: q.explanation,
    needsReview: q.import_status === "needs_review",
    requiresMedia: q.requires_media,
    enabled: q.enabled,
    notes: q.notes,
  };
}

